mapper.select:
SELECT A.CMPNY_CD AS cmpnyCd, C.CMPNY_NM AS cmpnyNm, A.GROUP_ID AS groupId, CASE WHEN #{languageCode} = 'en_US' THEN A.GROUP_ENG_NM ELSE A.GROUP_NM END AS groupNm, A.GROUP_ENG_NM AS groupEngNm, A.GROUP_CN AS groupCn, A.USE_FL AS useFl, DATE_FORMAT(A.CREATION_DT, '%Y-%m-%d') AS creationDt FROM CM_GROUP A INNER JOIN CM_CMPNY C ON C.CMPNY_CD = A.CMPNY_CD AND C.USE_FL = 'Y' WHERE 1=1
AND A.CMPNY_CD = #{cmpnyCd}
AND (A.GROUP_ID LIKE CONCAT('%', #{searchKeyword}, '%') OR A.GROUP_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR A.GROUP_ENG_NM LIKE CONCAT('%', #{searchKeyword}, '%'))
ORDER BY A.CMPNY_CD, A.GROUP_ID LIMIT #{recordCountPerPage} OFFSET #{offset}

SELECT COUNT(*) FROM CM_GROUP A INNER JOIN CM_CMPNY C ON C.CMPNY_CD = A.CMPNY_CD AND C.USE_FL = 'Y' WHERE 1=1
AND A.CMPNY_CD = #{cmpnyCd}
AND (A.GROUP_ID LIKE CONCAT('%', #{searchKeyword}, '%') OR A.GROUP_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR A.GROUP_ENG_NM LIKE CONCAT('%', #{searchKeyword}, '%'))
